(function(){
  var $=function(id){return document.getElementById(id)};

  function sniff(t){
    var head=t.split(/\r?\n/)[0]||'';
    var counts=[[',',0],[';',0],['\t',0],['|',0]].map(function(d){
      var n=0,q=false;
      for(var i=0;i<head.length;i++){
        var c=head[i];
        if(c==='"') q=!q; else if(c===d[0] && !q) n++;
      }
      return [d[0],n];
    });
    counts.sort(function(a,b){return b[1]-a[1]});
    return counts[0][1]>0 ? counts[0][0] : ',';
  }
  function parseCSV(text, delim){
    var rows=[], row=[], field='', q=false, i=0;
    text=text.replace(/^\uFEFF/,'');           // strip the BOM Excel adds
    while(i<text.length){
      var c=text[i];
      if(q){
        if(c==='"'){ if(text[i+1]==='"'){ field+='"'; i++; } else q=false; }
        else field+=c;
      } else {
        if(c==='"') q=true;
        else if(c===delim){ row.push(field); field=''; }
        else if(c==='\n'){ row.push(field); rows.push(row); row=[]; field=''; }
        else if(c==='\r'){ /* handled by the \n */ }
        else field+=c;
      }
      i++;
    }
    if(field!==''||row.length){ row.push(field); rows.push(row); }
    return rows.filter(function(r){ return r.length>1 || (r[0]||'').trim()!==''; });
  }
  function toCSV(rows, delim){
    return rows.map(function(r){
      return r.map(function(v){
        v = v==null ? '' : String(v);
        return /["\n\r]|\Q/.test(v.replace(/\\Q/g,delim)) || v.indexOf(delim)>=0
          ? '"'+v.replace(/"/g,'""')+'"' : v;
      }).join(delim);
    }).join('\r\n');
  }
  function download(name, text, mime){
    var b=new Blob([text],{type:mime||'text/csv;charset=utf-8'});
    var u=URL.createObjectURL(b), a=document.createElement('a');
    a.href=u; a.download=name; document.body.appendChild(a); a.click();
    setTimeout(function(){ URL.revokeObjectURL(u); a.remove(); }, 4000);
  }

  var rows=[];
  function currentDelim(text){
    var d=$('delim').value;
    return d==='auto' ? sniff(text) : d;
  }
  function render(){
    var text=$('raw').value;
    if(!text.trim()){ rows=[]; $('wrap').innerHTML=''; $('note').textContent='';
      ['nrows','ncols','nempty'].forEach(function(i){$(i).textContent='0'});
      if(window.WT) WT.resize(); return; }
    var d=currentDelim(text);
    rows=parseCSV(text,d);
    var mode=$('clean').value;
    if(mode!=='none'){
      rows=rows.map(function(r){return r.map(function(v){return v.trim()})});
      if(mode==='trimempty') rows=rows.filter(function(r){return r.some(function(v){return v!==''})});
    }
    var cols=rows.reduce(function(m,r){return Math.max(m,r.length)},0);
    var empty=0, ragged=0;
    rows.forEach(function(r){
      if(r.length!==cols) ragged++;
      for(var i=0;i<cols;i++) if(!(r[i]||'').trim()) empty++;
    });
    $('nrows').textContent=Math.max(0,rows.length-1);
    $('ncols').textContent=cols;
    $('nempty').textContent=empty;
    var names={',':'comma',';':'semicolon','\t':'tab','|':'pipe'};
    var msg='Read with the '+(names[d]||d)+' separator.';
    if(ragged) msg+=' '+ragged+' row'+(ragged>1?'s have':' has')+' a different number of columns to the header, which usually means a stray separator inside a value.';
    $('note').textContent=msg;
    // cap the DOM: a 50k row file must not build 50k table rows
    var LIMIT=200, shown=rows.slice(0,LIMIT+1);
    var head=shown[0]||[], body=shown.slice(1);
    var h='<table class="cv"><thead><tr>';
    for(var i=0;i<cols;i++) h+='<th>'+esc(head[i]||('Column '+(i+1)))+'</th>';
    h+='</tr></thead><tbody>';
    body.forEach(function(r){
      h+='<tr>';
      for(var i=0;i<cols;i++){
        var v=r[i]||'';
        h+='<td class="'+(v.trim()?'':'empty')+'">'+esc(v)+'</td>';
      }
      h+='</tr>';
    });
    h+='</tbody></table>';
    if(rows.length-1>LIMIT) h+='<div class="cv-more">Showing the first '+LIMIT+' rows of '+(rows.length-1)+'. Download or copy to get all of them.</div>';
    $('wrap').innerHTML=h;
    if(window.WT) WT.resize();
  }
  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
  function outCSV(){ return toCSV(rows, ','); }

  ['raw','delim','clean'].forEach(function(id){
    $(id).addEventListener('input',render); $(id).addEventListener('change',render);
  });
  $('pick').addEventListener('click',function(){$('file').click()});
  $('file').addEventListener('change',function(){ load(this.files[0]); });
  function load(f){
    if(!f) return;
    var r=new FileReader();
    r.onload=function(){ $('raw').value=String(r.result); render(); };
    r.onerror=function(){ $('note').textContent='That file could not be read.'; };
    r.readAsText(f);
  }
  var drop=$('drop');
  ['dragenter','dragover'].forEach(function(e){drop.addEventListener(e,function(ev){
    ev.preventDefault(); drop.classList.add('over');})});
  ['dragleave','drop'].forEach(function(e){drop.addEventListener(e,function(ev){
    ev.preventDefault(); drop.classList.remove('over');})});
  drop.addEventListener('drop',function(ev){ load(ev.dataTransfer.files[0]); });

  $('dl').addEventListener('click',function(){
    if(!rows.length){ $('note').textContent='There is nothing to download yet.'; return; }
    download('cleaned.csv', outCSV());
  });
  $('copy').addEventListener('click',function(){
    if(!rows.length) return;
    var ok=WT.copy(outCSV());
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy as CSV'},1400);
  });
  $('clear').addEventListener('click',function(){ $('raw').value=''; render(); });
  render();
})();
